    "workflow.basicConfigHelp": "Name the node, choose what it runs, and decide where it goes next.",
    "workflow.advancedConfig": "Advanced behavior",
    "workflow.advancedConfigHelp": "Use only when the node needs branching rules, field mapping, or custom parameters.",
    "workflow.advancedGuideKicker": "Fill guide",
    "workflow.advancedGuideTitle": "How to configure this node",
    "workflow.advancedGuideBody.execute": "Execution nodes usually need only an agent, skill, tool, and next stage. Use advanced fields when you want to pass specific upstream outputs or save named results.",
    "workflow.advancedGuideBody.control": "Control nodes decide where the workflow goes next. Configure the decision source first, then map possible results to target stage names.",
    "workflow.advancedGuideBody.default": "These fields are optional. Leave them empty unless this node needs custom routing, data mapping, or runtime options.",
    "workflow.advancedGuide.modelTitle": "Model route",
    "workflow.advancedGuide.modelBody": "Use a strong model only where it reduces rework, such as decomposition, aggregation, or audit. Keep worker nodes on cheaper routes with small budgets.",
    "workflow.advancedGuide.modelExample": "provider: backup\nmodel: small-worker\nmax_tokens: 900\ntemperature: 0.1",
    "workflow.advancedGuide.nextStrategyTitle": "Next-step rule",
    "workflow.advancedGuide.nextStrategyBody": "Usually leave this empty. Fill it only when the runtime should choose among multiple next stages by rule or model result.",
    "workflow.advancedGuide.nextStrategyExample": "auto\ncondition\nmodel",
    "workflow.advancedGuide.conditionTitle": "Condition",
    "workflow.advancedGuide.conditionBody": "Write an expression that evaluates to true or false, then map true and false in Routes.",
    "workflow.advancedGuide.conditionExample": "contains(stages.audit.outputs.risk, \"high\")",
    "workflow.advancedGuide.switchTitle": "Branch source",
    "workflow.advancedGuide.switchBody": "Point to the field whose value should choose a branch.",
    "workflow.advancedGuide.switchExample": "stages.classify.outputs.category",
    "workflow.advancedGuide.routesTitle": "Routes",
    "workflow.advancedGuide.routesBody": "Map a decision value to a target stage name. Add default as a fallback path.",
    "workflow.advancedGuide.routesExample": "true=security-review\nfalse=end\ndefault=manual-check",
    "workflow.advancedGuide.casesTitle": "Cases",
    "workflow.advancedGuide.casesBody": "Map possible branch source values to target stage names.",
    "workflow.advancedGuide.casesExample": "security=audit\ndocs=write-docs\ndefault=end",
    "workflow.advancedGuide.policyTitle": "Policy guard",
    "workflow.advancedGuide.policyBody": "Choose a reusable policy rule or write a policy expression, then route allow, deny, or block results.",
    "workflow.advancedGuide.policyExample": "allow=execute\ndeny=manual-review\nblock=end",
    "workflow.advancedGuide.inputTitle": "Input mapping",
    "workflow.advancedGuide.inputBody": "Left side is the name this node sees. Right side is the workflow input or an upstream stage output reference.",
    "workflow.advancedGuide.inputExample": "request=workflow.input\nplan=stages.plan.outputs.summary",
    "workflow.advancedGuide.outputsTitle": "Saved outputs",
    "workflow.advancedGuide.outputsBody": "Left side is the name downstream nodes will reference. Right side is where to read it from this node result.",
    "workflow.advancedGuide.outputsExample": "summary=result.summary\nfinal=result.output\nrisk=result.metadata.risk",
    "workflow.advancedGuide.paramsTitle": "Parameters",
    "workflow.advancedGuide.paramsBody": "Stable runtime options for this node. If you are not sure, leave this blank.",
    "workflow.advancedGuide.paramsExample": "timeout=60s\noutput_contract=summary, risks, next_steps",
    "workflow.advancedGuide.inputGateTitle": "Input gate form",
    "workflow.advancedGuide.inputGateBody": "Define fields the user must fill when the workflow pauses for missing information.",
    "workflow.advancedGuide.inputGateExample": "{\"fields\":[{\"name\":\"target\",\"label\":\"Target URL\",\"type\":\"url\",\"required\":true}]}",
    "workflow.advancedGuide.eachTitle": "Items to repeat over",
    "workflow.advancedGuide.eachBody": "Point to a list from the request or a previous stage output.",
    "workflow.advancedGuide.eachExample": "stages.scan.outputs.files",
    "workflow.advancedGuide.bodyStageTitle": "Body stage",
    "workflow.advancedGuide.bodyStageBody": "Name the stage that should run for each item or each loop iteration.",
    "workflow.advancedGuide.bodyStageExample": "review-file",
    "workflow.advancedGuide.loopTitle": "Loop stop condition",
    "workflow.advancedGuide.loopBody": "Use an expression that becomes true when the loop should stop. Also set a max iteration count.",
    "workflow.advancedGuide.loopExample": "stages.verify.outputs.passed",
    "workflow.advancedGuide.maxIterationsTitle": "Max iterations",
    "workflow.advancedGuide.maxIterationsBody": "Set a hard stop for the loop so a bad condition or model response cannot spin forever.",
    "workflow.advancedGuide.maxIterationsExample": "3",
    "workflow.advancedGuide.joinTitle": "Join wait list",
    "workflow.advancedGuide.joinBody": "List the branch stages that must finish before the workflow continues.",
    "workflow.advancedGuide.joinExample": "lint,audit,test",
