    "workflow.advancedGuideTitle": "这个节点应该怎么配置",
    "workflow.advancedGuideBody.execute": "执行节点通常只需要选择智能体、技能、工具和下一阶段。只有需要读取上游输出或保存命名结果时，再填写高级字段。",
    "workflow.advancedGuideBody.control": "控制节点负责决定流程下一步走向。先配置判断来源，再把可能结果映射到目标阶段名称。",
    "workflow.advancedGuideBody.default": "这些字段都是可选项。除非需要自定义路由、数据映射或运行参数，否则可以先留空。",
    "workflow.advancedGuide.modelTitle": "模型路由",
    "workflow.advancedGuide.modelBody": "只在能减少返工的阶段使用强模型，例如任务拆解、汇总或审计。执行型 worker 节点优先使用便宜路由和较小预算。",
    "workflow.advancedGuide.modelExample": "provider: backup\nmodel: small-worker\nmax_tokens: 900\ntemperature: 0.1",
    "workflow.advancedGuide.nextStrategyTitle": "下一步选择方式",
    "workflow.advancedGuide.nextStrategyBody": "通常留空。只有当前节点有多个下一阶段，并希望运行时按规则或模型结果选择时再填写。",
    "workflow.advancedGuide.nextStrategyExample": "auto\ncondition\nmodel",
    "workflow.advancedGuide.conditionTitle": "条件表达式",
    "workflow.advancedGuide.conditionBody": "填写会得到 true 或 false 的表达式，然后在路由中配置 true 和 false 分别去哪个阶段。",
    "workflow.advancedGuide.conditionExample": "contains(stages.audit.outputs.risk, \"high\")",
    "workflow.advancedGuide.switchTitle": "分支依据",
    "workflow.advancedGuide.switchBody": "填写用于决定分支的字段路径，运行时会读取这个值并匹配 Case。",
    "workflow.advancedGuide.switchExample": "stages.classify.outputs.category",
    "workflow.advancedGuide.routesTitle": "路由",
    "workflow.advancedGuide.routesBody": "把判断结果映射到目标阶段名称。建议添加 default 兜底路径。",
    "workflow.advancedGuide.routesExample": "true=security-review\nfalse=end\ndefault=manual-check",
    "workflow.advancedGuide.casesTitle": "Case 分支",
    "workflow.advancedGuide.casesBody": "把分支依据可能出现的值映射到目标阶段名称。",
    "workflow.advancedGuide.casesExample": "security=audit\ndocs=write-docs\ndefault=end",
    "workflow.advancedGuide.policyTitle": "策略守卫",
    "workflow.advancedGuide.policyBody": "选择可复用策略规则或填写策略表达式，然后配置 allow、deny、block 的去向。",
    "workflow.advancedGuide.policyExample": "allow=execute\ndeny=manual-review\nblock=end",
    "workflow.advancedGuide.inputTitle": "输入字段改名",
    "workflow.advancedGuide.inputBody": "左边是当前节点看到的名字，右边是工作流输入或上游阶段输出引用。",
    "workflow.advancedGuide.inputExample": "request=workflow.input\nplan=stages.plan.outputs.summary",
    "workflow.advancedGuide.outputsTitle": "输出保存为",
    "workflow.advancedGuide.outputsBody": "左边是后续节点引用的名字，右边是从当前节点结果中读取的位置。",
    "workflow.advancedGuide.outputsExample": "summary=result.summary\nfinal=result.output\nrisk=result.metadata.risk",
    "workflow.advancedGuide.paramsTitle": "高级参数",
    "workflow.advancedGuide.paramsBody": "这里填写稳定的运行选项或额外说明。不确定时可以留空。",
    "workflow.advancedGuide.paramsExample": "timeout=60s\noutput_contract=摘要、风险、下一步",
    "workflow.advancedGuide.inputGateTitle": "输入关口表单",
    "workflow.advancedGuide.inputGateBody": "定义工作流暂停时要让用户补充填写的字段。",
    "workflow.advancedGuide.inputGateExample": "{\"fields\":[{\"name\":\"target\",\"label\":\"目标网址\",\"type\":\"url\",\"required\":true}]}",
