    "settings.diagnosticRecommendation.mcp_network_disabled_advisory": "如果工具必须禁止联网，请使用禁用网络的容器隔离，或宿主机支持的网络命名空间隔离。",
    "settings.diagnosticRecommendation.mcp_env_allowlist_implicit_minimal": "保持白名单为空可获得更强隔离；只在确实需要时添加少量明确变量。",
    "settings.diagnosticRecommendation.mcp_env_allowlist_sensitive": "除非 MCP 服务必须直接调用对应服务，否则移除 API Key、Token、密码、私钥和云凭据。",
    "settings.diagnosticRecommendation.mcp_allowed_command_shell": "优先使用专用可执行文件或绝对路径 allowed_command_paths，不要把 shell 类命令放入启动白名单。",
    "settings.diagnosticRecommendation.mcp_isolation_none": "不可信 MCP 服务建议使用容器隔离；只有可信本地工具才保留无隔离模式。",
    "settings.diagnosticRecommendation.mcp_isolation_lifecycle_only": "如果工具需要真实的文件系统或权限边界，请改用容器隔离。",
