    "settings.diagnosticRecommendation.mcp_isolation_container": "信任这个边界前，请检查镜像来源、工作区挂载方式、资源限制和 capability 设置。",
    "settings.diagnosticRecommendation.mcp_isolation_container_network_open": "除非工具确实需要访问外网，否则把 isolation_options.network 设置为 disabled。",
    "settings.diagnosticRecommendation.mcp_container_image_floating_tag": "把镜像固定到明确版本标签或 digest。",
    "settings.diagnosticRecommendation.mcp_container_host_network": "除非工具明确需要宿主机网络且操作者接受该边界，否则避免使用 host 网络。",
    "settings.diagnosticRecommendation.mcp_container_workspace_rw": "只读工具使用 workspace_mount: ro，不需要工作区的工具使用 workspace_mount: none，只有必须写入时才保留 rw。",
    "settings.diagnosticRecommendation.mcp_container_resource_limits_missing": "设置 isolation_options.memory、isolation_options.memory_swap、isolation_options.cpus 和 isolation_options.pids_limit。",
    "settings.diagnosticRecommendation.mcp_container_user_missing": "把 isolation_options.user 设置为镜像支持的非 root UID:GID。",
    "settings.diagnosticRecommendation.mcp_container_no_new_privileges_missing": "不需要权限提升时，设置 isolation_options.no_new_privileges: true。",
    "settings.diagnosticRecommendation.mcp_container_cap_drop_missing": "除非服务需要特定 Linux capability，否则设置 isolation_options.cap_drop: all。",
    "settings.diagnosticRecommendation.mcp_container_readonly_rootfs_missing": "镜像不需要写入声明挂载以外位置时，设置 isolation_options.readonly_rootfs: true。",
