  "Entry marker. It does not run a model stage.": "入口标记，不会运行模型阶段。",
  "Use exactly one start node for visual clarity. Runtime execution follows stage order and next edges; start itself does not call a model.": "建议只保留一个开始节点，画布会更清晰。运行时按阶段顺序和 next 连线流转，开始节点本身不会调用模型。",
  "Run one configured agent with one skill prompt.": "使用一个已配置智能体和一个技能提示执行阶段。",
  "Run a selected skill, optionally with mapped inputs and outputs.": "运行选中的技能，并可按需配置输入和输出映射。",
  "Tool-focused stage. Agent permissions and approval policy still apply.": "面向工具调用的阶段，仍会遵守智能体权限和审批策略。",
  "Preferred tool metadata for this stage.": "此阶段优先使用的工具元数据。",
  "Declare a reusable multi-agent team context. Set params.execute=true to expand the team template into executable role stages.": "声明可复用的多智能体团队上下文。开启 params.execute 后，运行时会把团队模板展开成可执行的角色阶段。",
  "Route by a boolean expression such as contains(stage output, text).": "按布尔表达式分流，例如 contains(阶段输出, 文本)。",
  "Route by a resolved value with named cases and a default fallback.": "按解析出的值分流，并可设置命名 Case 和默认兜底路径。",
  "Allow, deny, or block a path based on a policy expression.": "按策略表达式允许、拒绝或阻断路径。",
  "Route or block based on prior acceptance criteria, verification results, artifact evidence, and tool errors.": "根据前置验收条目、验证结果、产物证据和工具错误来分流或阻断。",
  "Fan out to multiple branches. Branches run deterministically by default; set params.concurrent=true for eligible join-bound branches.": "扇出到多个分支。默认按确定顺序执行；满足汇合条件的分支可设置 params.concurrent=true 并发运行。",
  "Wait until required upstream branches complete, then continue.": "等待所需上游分支完成后继续。",
  "Collect or publish variables. Manual gates pause until the operator submits values.": "收集或发布变量。人工输入关口会暂停，直到用户提交所需值。",
  "Run one executable body stage once for each item, then publish aggregate iteration outputs.": "对每个项目运行一次指定主体阶段，然后发布汇总后的迭代输出。",
  "Run one executable body stage repeatedly until an expression passes or the max-iteration guard is reached.": "重复运行一个主体阶段，直到表达式通过或达到最大迭代次数。",
  "Run another workflow as a nested reusable unit and publish its run id, status, and summary.": "把另一个工作流作为可复用子单元运行，并发布它的运行 ID、状态和摘要。",
  "Pause for operator approval when a run is not pre-approved.": "当运行未预先批准时暂停，等待用户审批。",
  "Terminal marker. It does not run a model stage.": "终点标记，不会运行模型阶段。",
  "Use end nodes to make the canvas readable. Runtime stops when no next edge remains; end itself is visual-only.": "结束节点用于让画布更易读。运行时没有下一条连线就会停止，结束节点本身只是可视化标记。",

