  "Observed samples suggest this auxiliary route may reduce token spend; keep checking quality before making it the default path.": "观测样本显示这个辅助路由可能降低 Token 消耗；设为默认路径前仍要持续检查质量。",
  "Observed samples do not show a positive token-savings signal yet; the helper may be adding extra model calls without enough offset.": "观测样本还没有显示正向节省信号；这个助手可能增加了额外模型调用，抵消不够。",
