  "There is not enough measured prompt data to justify adding an extra auxiliary model call.": "当前提示词测量数据还不足以说明值得增加一次额外辅助模型调用。",
  "keep enabled for the current workload and compare route quality against main-model outputs": "当前工作负载下可以保持启用，并把路由质量与主模型输出对比。",
