function initialLanguage() {
  try {
    const url = new URL(window.location.href);
    const requested = url.searchParams.get("lang") || url.searchParams.get("locale");
    if (requested) {
      const normalized = requested.toLowerCase().startsWith("zh") ? "zh" : "en";
      localStorage.setItem("goflow.language", normalized);
      return normalized;
    }
  } catch {
    // Fall through to the persisted preference when URL parsing is unavailable.
  }
  return localStorage.getItem("goflow.language") || "en";
}

let language = initialLanguage();

