export function setLanguage(next) {
  language = next === "zh" ? "zh" : "en";
  localStorage.setItem("goflow.language", language);
}

export function currentLanguage() {
  return language;
}

function localizedObjectText(value) {
  if (!value || typeof value !== "object") return "";
  const keys = language === "zh"
    ? ["zh", "zh_CN", "zh-CN", "label_zh", "title_zh", "text_zh", "description_zh", "placeholder_zh", "group_zh", "help_zh", "label", "title", "text", "description", "placeholder", "group", "help", "en"]
    : ["en", "en_US", "en-US", "label", "title", "text", "description", "placeholder", "group", "help", "zh"];
  for (const key of keys) {
    if (typeof value[key] === "string" && value[key].trim()) return value[key].trim();
  }
  return "";
}

