export function localizedText(value) {
  const text = value && typeof value === "object" ? localizedObjectText(value) : String(value || "");
  if (!text || language !== "zh") return text;
  const exact = zhKnownText[text] || zhKnownTextLower[text.toLowerCase()];
  if (exact) return exact;
  for (const entry of zhKnownPatterns) {
    const match = text.match(entry.pattern);
    if (match) return entry.render(match);
  }
  return text;
}

export function t(key, vars) {
  const template = dictionaries[language]?.[key] || dictionaries.en[key] || key;
  if (!vars) return template;
  return Object.entries(vars).reduce((text, [name, value]) => {
    return text.replaceAll(`{${name}}`, String(value));
  }, template);
}

export function applyStaticTranslations(root = document) {
  staticI18nNodes(root, "[data-i18n]").forEach(node => {
    node.textContent = t(node.dataset.i18n);
  });
  [
    ["[data-i18n-aria-label]", "aria-label", "i18nAriaLabel"],
    ["[data-i18n-title]", "title", "i18nTitle"],
    ["[data-i18n-placeholder]", "placeholder", "i18nPlaceholder"]
  ].forEach(([selector, attribute, datasetKey]) => {
    staticI18nNodes(root, selector).forEach(node => {
      node.setAttribute(attribute, t(node.dataset[datasetKey]));
    });
  });
}

function staticI18nNodes(root, selector) {
  const nodes = [];
  if (root?.nodeType === 1 && root.matches(selector)) nodes.push(root);
  root?.querySelectorAll?.(selector).forEach(node => nodes.push(node));
  return nodes;
}
